import numpy as np, json, sys
def gen(n, seed, kind="lognormal"):
    r = np.random.default_rng(seed)
    if kind == "lognormal":
        x = r.lognormal(np.log(850), 0.9, n).astype(int) + 1
    elif kind == "uniform":
        x = r.integers(1, 6000, n)
    elif kind == "big":
        x = r.integers(1500, 4200, n)
    return [int(v) for v in x]
if __name__ == "__main__":
    n=int(sys.argv[1]); kind=sys.argv[2]
    json.dump(gen(n, 1, kind), open(f"/tmp/in_{kind}_{n}.json","w"))
EOF
