# instrumented copy of the reference to measure open-bin counts
import json, sys, time
def pack(lengths, params, stats):
    C = params["capacity"]; t = params["close_below"]; m = params["max_open"]; K = params["flush_every"]
    remaining = []; open_ids = []; out = []; tot=0; mx=0; caps=0
    for i, L in enumerate(lengths):
        if L > C:
            remaining.append(0); out.append(len(remaining) - 1); continue
        placed = -1
        for b in open_ids:
            if remaining[b] >= L:
                placed = b; break
        if placed < 0:
            remaining.append(C); placed = len(remaining) - 1; open_ids.append(placed)
        remaining[placed] -= L; out.append(placed)
        if remaining[placed] < t: open_ids.remove(placed)
        if len(open_ids) > m:
            caps+=1
            v = min(open_ids, key=lambda b: (remaining[b], b)); open_ids.remove(v)
        if (i + 1) % K == 0 and len(open_ids) >= 2: open_ids.remove(open_ids[0])
        tot+=len(open_ids); mx=max(mx,len(open_ids))
    stats.update(avg=tot/max(1,len(lengths)), mx=mx, caps=caps, bins=len(remaining))
    return out
kind=sys.argv[1]; n=int(sys.argv[2])
lengths=json.load(open(f"/tmp/in_{kind}_{n}.json")); params=json.load(open("/app/params.json"))
st={}; t0=time.time(); out=pack(lengths,params,st); print(kind, n, "ref time %.1fs"%(time.time()-t0), st)
